/** Returns a standalone SVG string of the logo with the given fill color. */
export function getLogoSvg(color: string): string {
  const paths = LOGO_PATHS.map(d => `<path d="${d}" fill="${color}"/>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 176 32" fill="none">${paths}</svg>`;
}

/** Returns a data: URL of the logo SVG (for use with Image / canvas). */
export function getLogoSvgDataUrl(color: string): string {
  const svg = getLogoSvg(color);
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

/**
 * Generates an embedded `<svg>` element string for the logo overlay,
 * positioned within a parent SVG's coordinate system.
 *
 * Returns empty string if logo is not enabled.
 */
export function generateLogoOverlaySvg(
  config: LogoOverlayConfig,
  canvasWidth: number,
  canvasHeight: number,
): string {
  if (!config.enabled) return '';

  const logoWidth = (config.size / 100) * canvasWidth;
  const logoHeight = logoWidth / LOGO_ASPECT_RATIO;

  // x/y are 0–100 percentages. At 0 the logo is flush-left/top, at 100 flush-right/bottom.
  const x = (config.x / 100) * (canvasWidth - logoWidth);
  const y = (config.y / 100) * (canvasHeight - logoHeight);

  const paths = LOGO_PATHS.map(d => `<path d="${d}" fill="${config.color}"/>`).join('');
  return `<svg x="${x}" y="${y}" width="${logoWidth}" height="${logoHeight}" viewBox="0 0 176 32" fill="none">${paths}</svg>`;
}

export type TextOverlayAlignment = 'left' | 'center' | 'right';
export type TextOverlayZOrder = 'above' | 'behind';
export type TextOverlayFontWeight = 400 | 500 | 600 | 700;

export interface TextOverlayPathData {
  d: string;
  transform: string;
}

export interface TextOverlayEntry {
  id: string;
  content: string;
  y: number;
  fontSize: number;
  fontWeight: TextOverlayFontWeight;
  alignment: TextOverlayAlignment;
  color: string;
  lineHeight: number;
  sidePadding: number;
  zOrder: TextOverlayZOrder;
  paths?: TextOverlayPathData[];
}

export interface TextOverlayConfig {
  enabled: boolean;
  entries: TextOverlayEntry[];
}

export const DEFAULT_TEXT_OVERLAY_CONFIG: TextOverlayConfig = {
  enabled: false,
  entries: [],
};

export const DEFAULT_TEXT_OVERLAY_ENTRY: Omit<TextOverlayEntry, 'id'> = {
  content: '',
  y: 50,
  fontSize: 5,
  fontWeight: 400,
  alignment: 'center',
  color: '#FCFCFC',
  lineHeight: 1.4,
  sidePadding: 0,
  zOrder: 'above',
};

const VALID_FONT_WEIGHTS: TextOverlayFontWeight[] = [400, 500, 600, 700];

export function isValidFontWeight(w: number): w is TextOverlayFontWeight {
  return VALID_FONT_WEIGHTS.includes(w as TextOverlayFontWeight);
}

function escapeXml(str: string): string {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

export function generateTextOverlaySvg(
  config: TextOverlayConfig | undefined,
  _canvasWidth: number,
  _canvasHeight: number,
  position: TextOverlayZOrder,
): string {
  if (!config?.enabled) return '';

  const entries = config.entries.filter(e => e.zOrder === position && e.content.trim());
  if (entries.length === 0) return '';

  return entries.map(entry => {
    if (!entry.paths?.length) return '';
    const paths = entry.paths
      .map(p => {
        const attrs = [`d="${escapeXml(p.d)}"`, `fill="${escapeXml(entry.color)}"`];
        if (p.transform) attrs.push(`transform="${escapeXml(p.transform)}"`);
        return `<path ${attrs.join(' ')}/>`;
      })
      .join('');
    return `<g>${paths}</g>`;
  }).join('');
}

// Types

export type FillType = 'linear' | 'radial' | 'angular' | 'diamond' | 'square' | 'box';

export type SeedableParam =
  | 'threshold'
  | 'gamma'
  | 'frequency'
  | 'contrast'
  | 'directionalNeighbors'
  | 'directionDensity'
  | 'fillAmount';

export type CropDirection = 'width' | 'height';
export type ElongateAxis = 'none' | 'width' | 'height';

export interface FragmentConfig {
  /** Density threshold for noise (0-1) */
  threshold: number;
  /** Gamma correction for contrast (0.1-3) */
  gamma: number;
  /** Noise frequency/detail level (0.01-0.5) */
  frequency: number;
  /** Noise contrast adjustment (0.1-3) */
  contrast: number;
  /** Base random seed (0-1) */
  seed: number;
  /** Boundary fragment extent (0-999) */
  directionalNeighbors: number;
  /** Number of boundary fragments (0-999) */
  directionDensity: number;
  /** Fill percentage (0-100) */
  fillAmount: number;
  /** Fill gradient type */
  fillType: FillType;
  /** Invert fill direction */
  invertFill: boolean;
  /** Foreground color (hex) */
  foregroundColor: string;
  /** Background color (hex) */
  backgroundColor: string;
  /** Cell size in pixels */
  cellSize: number;
  /** Canvas width in pixels */
  canvasWidth?: number;
  /** Canvas height in pixels */
  canvasHeight?: number;
  /** Which parameter to vary based on seed string (optional, defaults to 'frequency') */
  seedParam?: SeedableParam;
  /** Allow cropping mode - enables partial cells at edges */
  allowCropping?: boolean;
  /** Which axis to crop: 'width' crops rightmost column, 'height' crops bottom row */
  cropDirection?: CropDirection;
  /** Which axis to stretch cells along ('none' = square cells) */
  elongateAxis?: ElongateAxis;
  /** Multiplier for cell stretch (e.g. 4 with width axis = cells are 4x wide) */
  elongateAmount?: number;
}

export interface GenerateFragmentSvgOptions {
  /** Any string to use as seed (e.g., principal ID, username). If omitted, uses config.seed directly. */
  seed?: string;
  /** The fragment configuration object */
  config: FragmentConfig;
}

export interface GenerateFragmentDiffSvgOptions {
  seedA: string;
  seedB: string;
  config: FragmentConfig;
}

/**
 * Options for generating a diff SVG from two full configurations.
 * Used when animation is enabled and both From and To panels have independent params.
 */
export interface GenerateFragmentDiffFromConfigsOptions {
  /** The "From" configuration (pattern shown by default) */
  fromConfig: FragmentConfig;
  /** The "To" configuration (pattern shown on hover) */
  toConfig: FragmentConfig;
  /** Optional seed string for the "From" pattern (e.g. article title). Overrides the seedParam in fromConfig. */
  fromSeed?: string;
  /** Optional seed string for the "To" pattern. Overrides the seedParam in toConfig. */
  toSeed?: string;
}

/**
 * Animation settings exported in JSON format (v2.1.0+).
 * Nested structure for forwards compatibility with future animation settings.
 */
export interface AnimationSettings {
  /** Animation duration in milliseconds (100-5000, default: 600) */
  duration: number;
}

/**
 * Complete JSON export structure from Fragment Maker.
 * Use this type when importing exported JSON files in your application.
 *
 * @example
 * ```typescript
 * import type { FragmentExport } from './generateFragmentSvg';
 *
 * const fragmentExport: FragmentExport = await fetch('/fragment-config.json').then(r => r.json());
 *
 * // Access animation duration (v2.1.0+)
 * const duration = fragmentExport.animation?.duration ?? 600;
 * ```
 */
export interface FragmentExport {
  /** Export format version (e.g., "2.2.0") */
  version: string;
  /** ISO timestamp of export */
  exportedAt: string;
  /** Main fragment configuration (the "From" pattern when animation is enabled) */
  config: FragmentConfig;
  /** Optional animation settings (v2.1.0+). Present only when animation is enabled. */
  animation?: AnimationSettings;
  /** Optional "To" configuration for animation. Present only when animation is enabled. */
  toConfig?: FragmentConfig;
  /** Font data for text rendering (v2.2.0+). Present when any state uses text. */
  fonts?: SerializedFontData;
  /** State type for the "From" state (v2.2.0+). Defaults to 'pattern' if absent. */
  fromStateType?: 'pattern' | 'text';
  /** State type for the "To" state (v2.2.0+). Defaults to 'pattern' if absent. */
  toStateType?: 'pattern' | 'text';
  /** Text configuration for the "From" state (v2.2.0+). */
  fromTextConfig?: TextConfig;
  /** Text configuration for the "To" state (v2.2.0+). */
  toTextConfig?: TextConfig;
  /** Logo overlay configuration (v2.3.0+). Present only when logo is enabled. */
  logo?: LogoOverlayConfig;
  /** Text overlay configuration (v2.4.0+). Present only when text overlay is enabled. */
  textOverlay?: TextOverlayConfig;
}

// Constants

export const PARAM_RANGES: Record<SeedableParam, { min: number; max: number; step: number }> = {
  threshold: { min: 0, max: 1, step: 0.01 },
  gamma: { min: 0.1, max: 3, step: 0.1 },
  frequency: { min: 0.01, max: 0.5, step: 0.01 },
  contrast: { min: 0.1, max: 3, step: 0.1 },
  directionalNeighbors: { min: 0, max: 999, step: 1 },
  directionDensity: { min: 0, max: 999, step: 1 },
  fillAmount: { min: 0, max: 100, step: 1 },
};

// Hash Functions

/**
 * djb2 hash algorithm - converts a string to a 32-bit unsigned integer.
 */
export function djb2Hash(str: string): number {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) + hash) ^ char;
  }
  return hash >>> 0;
}

/**
 * Normalizes a djb2 hash value to a range [0, 1].
 */
export function normalizeHash(hash: number): number {
  return hash / 0xffffffff;
}

// Internal Functions

function seededRandom(seed: number, x: number, y: number): number {
  const value = Math.sin(seed * 12.9898 + x * 78.233 + y * 43.758) * 43758.5453;
  return value - Math.floor(value);
}

function calculateFillThreshold(
  x: number,
  y: number,
  fillType: FillType,
  cols: number,
  rows: number
): number {
  const centerX = cols / 2;
  const centerY = rows / 2;

  switch (fillType) {
    case 'linear':
      return (y / rows) * 100;

    case 'radial': {
      const dx = x - centerX;
      const dy = y - centerY;
      const distance = Math.sqrt(dx * dx + dy * dy);
      const maxDistance = Math.sqrt(centerX * centerX + centerY * centerY);
      return (distance / maxDistance) * 100;
    }

    case 'angular': {
      const angle = Math.atan2(y - centerY, x - centerX);
      return ((angle + Math.PI) / (2 * Math.PI)) * 100;
    }

    case 'diamond': {
      const diamondDistance = Math.abs(x - centerX) + Math.abs(y - centerY);
      const maxDiamondDistance = centerX + centerY;
      return (diamondDistance / maxDiamondDistance) * 100;
    }

    case 'square': {
      const squareDistance = Math.max(Math.abs(x - centerX), Math.abs(y - centerY));
      const maxSquareDistance = Math.max(centerX, centerY);
      return (squareDistance / maxSquareDistance) * 100;
    }

    case 'box': {
      const distToEdge = Math.min(x, y, cols - 1 - x, rows - 1 - y);
      const maxDist = (Math.min(cols, rows) - 1) / 2;
      return maxDist > 0 ? (1 - distToEdge / maxDist) * 100 : 0;
    }
  }
}

function createBoundaryFragment(
  grid: boolean[][],
  startX: number,
  startY: number,
  color: boolean,
  seedOffset: number,
  seed: number,
  directionalNeighbors: number
): void {
  if (directionalNeighbors === 0) return;

  const actualRows = grid.length;
  const actualCols = grid[0]?.length || 0;

  if (actualCols === 0 || actualRows === 0) return;

  const directionSeed = seededRandom(seed, seedOffset, 6000);
  const isHorizontal = directionSeed > 0.5;

  const signSeed = seededRandom(seed, seedOffset, 6001);
  const direction = signSeed > 0.5 ? 1 : -1;

  const sizeSeed = seededRandom(seed, seedOffset, 6002);
  const maxLength = Math.min(Math.floor(directionalNeighbors / 50) + 2, 12);
  const length = Math.floor(sizeSeed * maxLength) + 2;

  const thicknessSeed = seededRandom(seed, seedOffset, 6003);
  const thickness = thicknessSeed > 0.7 ? 2 : 1;

  if (isHorizontal) {
    for (let i = 0; i < length; i++) {
      const x = startX + i * direction;
      if (x >= 0 && x < actualCols) {
        for (let t = 0; t < thickness; t++) {
          const y = startY + t;
          if (y >= 0 && y < actualRows) {
            grid[y][x] = color;
          }
        }
      }
    }
  } else {
    for (let i = 0; i < length; i++) {
      const y = startY + i * direction;
      if (y >= 0 && y < actualRows) {
        for (let t = 0; t < thickness; t++) {
          const x = startX + t;
          if (x >= 0 && x < actualCols) {
            grid[y][x] = color;
          }
        }
      }
    }
  }
}

function applyDirectionalNeighbors(
  grid: boolean[][],
  seed: number,
  directionalNeighbors: number,
  directionDensity: number
): void {
  if (directionDensity === 0) return;
  if (!grid || grid.length === 0 || !grid[0] || grid[0].length === 0) return;

  const actualRows = grid.length;
  const actualCols = grid[0].length;
  const boundaryCells: { x: number; y: number; color: boolean }[] = [];

  for (let y = 0; y < actualRows; y++) {
    for (let x = 0; x < actualCols; x++) {
      const currentColor = grid[y][x];
      const neighbors = [
        { x: x - 1, y },
        { x: x + 1, y },
        { x, y: y - 1 },
        { x, y: y + 1 },
      ];

      const isBoundary = neighbors.some(
        (n) =>
          n.x >= 0 &&
          n.x < actualCols &&
          n.y >= 0 &&
          n.y < actualRows &&
          grid[n.y][n.x] !== currentColor
      );

      if (isBoundary) {
        boundaryCells.push({ x, y, color: currentColor });
      }
    }
  }

  const numFragments = Math.min(directionDensity, boundaryCells.length);
  for (let i = 0; i < numFragments; i++) {
    const randomSeed = seededRandom(seed, i, 5000);
    const index = Math.floor(randomSeed * boundaryCells.length);
    const cell = boundaryCells[index];
    createBoundaryFragment(grid, cell.x, cell.y, cell.color, i, seed, directionalNeighbors);
  }
}

// Exported Internal Functions (for tool use)

/**
 * @internal Generates a 2D boolean grid. Exported for tool use only.
 */
export function generateGrid(
  cols: number,
  rows: number,
  seed: number,
  threshold: number,
  gamma: number,
  frequency: number,
  contrast: number,
  fillAmount: number,
  fillType: FillType,
  invertFill: boolean,
  directionalNeighbors: number,
  directionDensity: number
): boolean[][] {
  const grid: boolean[][] = [];

  for (let y = 0; y < rows; y++) {
    const row: boolean[] = [];
    for (let x = 0; x < cols; x++) {
      let noise = seededRandom(seed, x * frequency, y * frequency);
      noise = Math.pow(noise, gamma);
      noise = (noise - 0.5) * contrast + 0.5;
      noise = Math.max(0, Math.min(1, noise));

      const fillThreshold = calculateFillThreshold(x, y, fillType, cols, rows);
      const effectiveFillAmount = invertFill ? 100 - fillAmount : fillAmount;
      const shouldFill = invertFill
        ? fillThreshold > effectiveFillAmount
        : fillThreshold <= effectiveFillAmount;

      row.push(shouldFill && noise > threshold);
    }
    grid.push(row);
  }

  applyDirectionalNeighbors(grid, seed, directionalNeighbors, directionDensity);
  return grid;
}

/**
 * Upscale an entity-level grid to base-cell-level by repeating each cell
 * along the elongation axis. This preserves the visual elongation effect
 * while producing a grid at base-cell resolution (needed for diffs with text).
 */
export function upscaleGridToBaseLevel(
  entityGrid: boolean[][],
  elongateAxis: ElongateAxis,
  elongateAmount: number,
  baseCols: number,
  baseRows: number,
): boolean[][] {
  if (elongateAxis === 'none' || elongateAmount <= 1) return entityGrid;

  const result: boolean[][] = [];

  if (elongateAxis === 'height') {
    // Each entity row maps to `elongateAmount` base rows
    const entityRows = entityGrid.length;
    for (let ey = 0; ey < entityRows; ey++) {
      for (let r = 0; r < elongateAmount && result.length < baseRows; r++) {
        result.push([...entityGrid[ey]]);
      }
    }
  } else {
    // elongateAxis === 'width': each entity col maps to `elongateAmount` base cols
    for (let y = 0; y < entityGrid.length && y < baseRows; y++) {
      const row: boolean[] = [];
      for (let ex = 0; ex < entityGrid[y].length; ex++) {
        const val = entityGrid[y][ex];
        for (let r = 0; r < elongateAmount && row.length < baseCols; r++) {
          row.push(val);
        }
      }
      result.push(row);
    }
  }

  return result;
}

export interface GridToSvgOptions {
  allowCropping?: boolean;
  cropDirection?: CropDirection;
  /** Effective cell width (may differ from cellSize when elongated) */
  cellWidth?: number;
  /** Effective cell height (may differ from cellSize when elongated) */
  cellHeight?: number;
}

/**
 * @internal Converts a boolean grid to SVG. Exported for tool use only.
 */
export function gridToSvg(
  grid: boolean[][],
  cols: number,
  rows: number,
  cellSize: number,
  width: number,
  foregroundColor: string,
  backgroundColor: string,
  height: number,
  options?: GridToSvgOptions
): string {
  const outputWidth = width;
  const outputHeight = height;
  const cw = options?.cellWidth ?? cellSize;
  const ch = options?.cellHeight ?? cellSize;

  const viewBoxWidth = outputWidth;
  const viewBoxHeight = outputHeight;

  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${outputWidth}" height="${outputHeight}" viewBox="0 0 ${viewBoxWidth} ${viewBoxHeight}" shape-rendering="crispEdges">`;

  // Background rect to fill the entire canvas
  svg += `<rect x="0" y="0" width="${viewBoxWidth}" height="${viewBoxHeight}" fill="${backgroundColor}"/>`;

  // Render cells - entities at the edge are clipped to canvas bounds
  for (let y = 0; y < Math.min(rows, grid.length); y++) {
    for (let x = 0; x < Math.min(cols, grid[y]?.length || 0); x++) {
      if (!grid[y][x]) continue;

      // Clip to canvas bounds (handles partial entities at edges)
      const rectWidth = Math.min(cw, outputWidth - x * cw);
      const rectHeight = Math.min(ch, outputHeight - y * ch);

      if (rectWidth <= 0 || rectHeight <= 0) continue;

      svg += `<rect x="${x * cw}" y="${y * ch}" width="${rectWidth}" height="${rectHeight}" fill="${foregroundColor}"/>`;
    }
  }

  svg += '</svg>';
  return svg;
}

// Shared Helpers

interface Dimensions {
  cols: number;
  rows: number;
  width: number;
  height: number;
  cellWidth: number;
  cellHeight: number;
}

/**
 * Compute effective cell dimensions from base cellSize + elongation settings.
 */
export function getCellDimensions(config: {
  cellSize: number;
  elongateAxis?: ElongateAxis;
  elongateAmount?: number;
}): { cellWidth: number; cellHeight: number } {
  const { cellSize, elongateAxis = 'none', elongateAmount = 1 } = config;
  const amount = Math.max(1, Math.round(elongateAmount));
  return {
    cellWidth: elongateAxis === 'width' ? cellSize * amount : cellSize,
    cellHeight: elongateAxis === 'height' ? cellSize * amount : cellSize,
  };
}

function computeDimensions(config: {
  cellSize: number;
  canvasWidth?: number;
  canvasHeight?: number;
  allowCropping?: boolean;
  cropDirection?: CropDirection;
  elongateAxis?: ElongateAxis;
  elongateAmount?: number;
}): Dimensions {
  const {
    canvasWidth = 1056,
    canvasHeight = 1056,
    allowCropping = false,
    cropDirection = 'height',
  } = config;

  const { cellWidth, cellHeight } = getCellDimensions(config);

  const width = canvasWidth;
  const height = canvasHeight;

  // Grid cols/rows are at entity (elongated cell) level.
  // Use ceil so entities at the edge can be partially visible (clipped by viewBox).
  let cols: number;
  let rows: number;
  if (allowCropping) {
    if (cropDirection === 'width') {
      cols = Math.ceil(width / cellWidth);
      rows = Math.floor(height / cellHeight);
    } else {
      cols = Math.floor(width / cellWidth);
      rows = Math.ceil(height / cellHeight);
    }
  } else {
    cols = Math.ceil(width / cellWidth);
    rows = Math.ceil(height / cellHeight);
  }

  return { cols, rows, width, height, cellWidth, cellHeight };
}

/**
 * Compute base-cell-level dimensions (ignoring elongation) for text grids.
 */
function computeBaseDimensions(config: {
  cellSize: number;
  canvasWidth?: number;
  canvasHeight?: number;
  allowCropping?: boolean;
  cropDirection?: CropDirection;
}): { baseCols: number; baseRows: number } {
  const { cellSize, canvasWidth = 1056, canvasHeight = 1056, allowCropping = false, cropDirection = 'height' } = config;
  let baseCols: number;
  let baseRows: number;
  if (allowCropping) {
    if (cropDirection === 'width') {
      baseCols = Math.ceil(canvasWidth / cellSize);
      baseRows = Math.floor(canvasHeight / cellSize);
    } else {
      baseCols = Math.floor(canvasWidth / cellSize);
      baseRows = Math.ceil(canvasHeight / cellSize);
    }
  } else {
    baseCols = Math.floor(canvasWidth / cellSize);
    baseRows = Math.floor(canvasHeight / cellSize);
  }
  return { baseCols, baseRows };
}

function applySeededParam(
  config: Omit<FragmentConfig, 'seedParam'>,
  seedString: string,
  seedParam: SeedableParam
): Omit<FragmentConfig, 'seedParam'> {
  const hash = djb2Hash(seedString);
  const normalizedHash = normalizeHash(hash);
  const paramRange = PARAM_RANGES[seedParam];
  const seededValue = paramRange.min + normalizedHash * (paramRange.max - paramRange.min);
  const roundedSeededValue =
    paramRange.step >= 1
      ? Math.round(seededValue)
      : Math.round(seededValue / paramRange.step) * paramRange.step;

  return { ...config, [seedParam]: roundedSeededValue };
}

function gridFromConfig(config: Omit<FragmentConfig, 'seedParam'>, dims: Dimensions): boolean[][] {
  return generateGrid(
    dims.cols, dims.rows,
    config.seed, config.threshold, config.gamma, config.frequency,
    config.contrast, config.fillAmount, config.fillType, config.invertFill,
    config.directionalNeighbors, config.directionDensity
  );
}

// Shared Rendering Pipeline

interface RenderParams {
  config: Omit<FragmentConfig, 'seedParam'>;
}

/**
 * @internal Shared dimension→grid→svg pipeline used by both generateFragmentSvg and generateFragmentSvgDirect.
 */
function renderConfigToSvg(params: RenderParams): string {
  const { config } = params;

  const dims = computeDimensions(config);
  if (dims.cols <= 0 || dims.rows <= 0) {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><text x="10" y="50" fill="red">Invalid dimensions</text></svg>`;
  }

  const grid = gridFromConfig(config, dims);

  return gridToSvg(
    grid, dims.cols, dims.rows, config.cellSize, dims.width,
    config.foregroundColor, config.backgroundColor, dims.height,
    { cellWidth: dims.cellWidth, cellHeight: dims.cellHeight }
  );
}

// Main Exported Functions

/**
 * Generates a Fragment pattern SVG with explicit parameter values (no seed string).
 * Used by the tool's grid preview. Shares the same rendering pipeline as generateFragmentSvg.
 *
 * @param config - The fragment configuration object
 * @returns SVG string
 */
export function generateFragmentSvgDirect(config: Omit<FragmentConfig, 'seedParam'>): string {
  return renderConfigToSvg({ config });
}

/**
 * Generates a Fragment pattern SVG from a seed string and configuration.
 *
 * The seed string is hashed using djb2 to produce a deterministic value
 * that modifies one parameter (specified by config.seedParam, defaults to 'frequency').
 *
 * @param options - Generation options
 * @param options.seed - Any string to use as seed (e.g., principal ID, username)
 * @param options.config - The fragment configuration object
 * @returns SVG string
 */
export function generateFragmentSvg(options: GenerateFragmentSvgOptions): string {
  const { seed: seedString, config } = options;
  const { seedParam = 'frequency', ...rest } = config;

  if (seedString === undefined) {
    return renderConfigToSvg({ config: rest });
  }

  const seededConfig = applySeededParam(rest, seedString, seedParam);
  return renderConfigToSvg({ config: seededConfig });
}

/**
 * @internal Shared helper for building diff SVGs from two grids.
 */
function buildDiffSvg(
  gridA: boolean[][],
  gridB: boolean[][],
  cols: number,
  rows: number,
  cw: number,
  ch: number,
  width: number,
  height: number,
  foregroundColor: string,
  backgroundColor: string,
): string {
  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" shape-rendering="crispEdges">`;
  svg += `<rect x="0" y="0" width="${width}" height="${height}" fill="${backgroundColor}"/>`;

  for (let y = 0; y < Math.min(rows, gridA.length, gridB.length); y++) {
    for (let x = 0; x < Math.min(cols, gridA[y]?.length || 0, gridB[y]?.length || 0); x++) {
      const inA = gridA[y][x];
      const inB = gridB[y][x];
      if (!inA && !inB) continue;

      const rectWidth = Math.min(cw, width - x * cw);
      const rectHeight = Math.min(ch, height - y * ch);
      if (rectWidth <= 0 || rectHeight <= 0) continue;

      const pos = `x="${x * cw}" y="${y * ch}" width="${rectWidth}" height="${rectHeight}" fill="${foregroundColor}"`;

      if (inA && inB) {
        svg += `<rect ${pos}/>`;
      } else if (inA) {
        svg += `<rect ${pos} data-g="a"/>`;
      } else {
        svg += `<rect ${pos} data-g="b" style="opacity:0"/>`;
      }
    }
  }

  svg += '</svg>';
  return svg;
}

export interface MixedCellDiffOptions {
  /** Pattern grid at entity level */
  entityGrid: boolean[][];
  /** Text grid at base-cell level */
  textGrid: boolean[][];
  elongateAxis: ElongateAxis;
  elongateAmount: number;
  baseCols: number;
  baseRows: number;
  cellSize: number;
  width: number;
  height: number;
  foregroundColor: string;
  backgroundColor: string;
  /** true = pattern is "from" (visible, animates out), text is "to" */
  patternIsFrom: boolean;
}

/**
 * Build a diff SVG for pattern↔text with elongation.
 * Pattern-only cells are emitted as entity-sized rects (whole bars) so they
 * animate as single DOM elements. Text-only cells are individual base-cell rects.
 * Shared cells (in both pattern and text) are base-cell rects (always visible).
 */
export function buildMixedCellDiffSvg(opts: MixedCellDiffOptions): string {
  const { entityGrid, textGrid, elongateAxis, elongateAmount,
          baseCols, baseRows, cellSize, width, height,
          foregroundColor, backgroundColor, patternIsFrom } = opts;

  const stretchX = elongateAxis === 'width' ? elongateAmount : 1;
  const stretchY = elongateAxis === 'height' ? elongateAmount : 1;
  const entityCols = entityGrid[0]?.length || 0;
  const entityRows = entityGrid.length;

  const pTag = patternIsFrom ? ' data-g="a"' : ' data-g="b" style="opacity:0"';
  const tTag = patternIsFrom ? ' data-g="b" style="opacity:0"' : ' data-g="a"';

  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" shape-rendering="crispEdges">`;
  svg += `<rect x="0" y="0" width="${width}" height="${height}" fill="${backgroundColor}"/>`;

  // Track which base cells have been emitted (shared or pattern-only entity rects)
  const emitted = new Set<number>(); // by * baseCols + bx
  const key = (bx: number, by: number) => by * baseCols + bx;

  // 1. Process each entity — emit shared cells individually, pattern-only as merged rects
  for (let ey = 0; ey < entityRows; ey++) {
    for (let ex = 0; ex < entityCols; ex++) {
      if (!entityGrid[ey][ex]) continue;

      const baseXStart = ex * stretchX;
      const baseYStart = ey * stretchY;
      const baseXEnd = Math.min(baseXStart + stretchX, baseCols);
      const baseYEnd = Math.min(baseYStart + stretchY, baseRows);

      if (elongateAxis === 'width') {
        // Width stretch: merge pattern-only runs along X within each row
        for (let by = baseYStart; by < baseYEnd; by++) {
          let runStart = -1;
          for (let bx = baseXStart; bx <= baseXEnd; bx++) {
            const inText = bx < baseXEnd && (textGrid[by]?.[bx] ?? false);
            const isPatternOnly = bx < baseXEnd && !inText;

            if (isPatternOnly && runStart < 0) runStart = bx;

            if (!isPatternOnly || bx === baseXEnd) {
              if (runStart >= 0) {
                // Emit merged pattern-only rect
                const rw = Math.min((bx - runStart) * cellSize, width - runStart * cellSize);
                const rh = Math.min(cellSize, height - by * cellSize);
                if (rw > 0 && rh > 0) {
                  svg += `<rect x="${runStart * cellSize}" y="${by * cellSize}" width="${rw}" height="${rh}" fill="${foregroundColor}"${pTag}/>`;
                }
                for (let i = runStart; i < bx; i++) emitted.add(key(i, by));
                runStart = -1;
              }
              // Emit shared cell
              if (bx < baseXEnd && inText) {
                const rw = Math.min(cellSize, width - bx * cellSize);
                const rh = Math.min(cellSize, height - by * cellSize);
                if (rw > 0 && rh > 0) {
                  svg += `<rect x="${bx * cellSize}" y="${by * cellSize}" width="${rw}" height="${rh}" fill="${foregroundColor}"/>`;
                }
                emitted.add(key(bx, by));
              }
            }
          }
        }
      } else {
        // Height stretch: merge pattern-only runs along Y within each column
        for (let bx = baseXStart; bx < baseXEnd; bx++) {
          let runStart = -1;
          for (let by = baseYStart; by <= baseYEnd; by++) {
            const inText = by < baseYEnd && (textGrid[by]?.[bx] ?? false);
            const isPatternOnly = by < baseYEnd && !inText;

            if (isPatternOnly && runStart < 0) runStart = by;

            if (!isPatternOnly || by === baseYEnd) {
              if (runStart >= 0) {
                const rw = Math.min(cellSize, width - bx * cellSize);
                const rh = Math.min((by - runStart) * cellSize, height - runStart * cellSize);
                if (rw > 0 && rh > 0) {
                  svg += `<rect x="${bx * cellSize}" y="${runStart * cellSize}" width="${rw}" height="${rh}" fill="${foregroundColor}"${pTag}/>`;
                }
                for (let i = runStart; i < by; i++) emitted.add(key(bx, i));
                runStart = -1;
              }
              if (by < baseYEnd && inText) {
                const rw = Math.min(cellSize, width - bx * cellSize);
                const rh = Math.min(cellSize, height - by * cellSize);
                if (rw > 0 && rh > 0) {
                  svg += `<rect x="${bx * cellSize}" y="${by * cellSize}" width="${rw}" height="${rh}" fill="${foregroundColor}"/>`;
                }
                emitted.add(key(bx, by));
              }
            }
          }
        }
      }
    }
  }

  // 2. Emit text-only cells (not covered by any pattern entity)
  for (let by = 0; by < baseRows; by++) {
    for (let bx = 0; bx < baseCols; bx++) {
      if (!(textGrid[by]?.[bx])) continue;
      if (emitted.has(key(bx, by))) continue;

      const rw = Math.min(cellSize, width - bx * cellSize);
      const rh = Math.min(cellSize, height - by * cellSize);
      if (rw <= 0 || rh <= 0) continue;

      svg += `<rect x="${bx * cellSize}" y="${by * cellSize}" width="${rw}" height="${rh}" fill="${foregroundColor}"${tTag}/>`;
    }
  }

  svg += '</svg>';
  return svg;
}

/**
 * Generates a single diff SVG from two seed strings.
 * Cells shared by both patterns are static. Cells unique to pattern A get data-g="a" (visible, animate off).
 * Cells unique to pattern B get data-g="b" (hidden, animate on).
 */
export function generateFragmentDiffSvg(options: GenerateFragmentDiffSvgOptions): string {
  const { seedA, seedB, config } = options;
  const { seedParam = 'frequency', ...rest } = config;

  const dims = computeDimensions(rest);
  if (dims.cols <= 0 || dims.rows <= 0) {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><text x="10" y="50" fill="red">Invalid dimensions</text></svg>`;
  }

  const configA = applySeededParam(rest, seedA, seedParam);
  const configB = applySeededParam(rest, seedB, seedParam);

  const gridA = gridFromConfig(configA, dims);
  const gridB = gridFromConfig(configB, dims);

  const { cols, rows, width, height, cellWidth, cellHeight } = dims;
  const { foregroundColor, backgroundColor } = rest;

  return buildDiffSvg(gridA, gridB, cols, rows, cellWidth, cellHeight, width, height, foregroundColor, backgroundColor);
}

/**
 * Options for generating a diff SVG from raw boolean grids.
 * Used when grids come from different sources (pattern generator, text generator, etc.)
 */
export interface GenerateDiffFromGridsOptions {
  /** The "From" grid (pattern shown by default) */
  gridFrom: boolean[][];
  /** The "To" grid (pattern shown on hover) */
  gridTo: boolean[][];
  /** Grid columns */
  cols: number;
  /** Grid rows */
  rows: number;
  /** Cell size in pixels */
  cellSize: number;
  /** Canvas width in pixels */
  width: number;
  /** Canvas height in pixels */
  height: number;
  /** Foreground color (hex) */
  foregroundColor: string;
  /** Background color (hex) */
  backgroundColor: string;
  /** Allow cropping mode */
  allowCropping?: boolean;
  /** Which axis to crop */
  cropDirection?: CropDirection;
  /** Effective cell width (may differ from cellSize when elongated) */
  cellWidth?: number;
  /** Effective cell height (may differ from cellSize when elongated) */
  cellHeight?: number;
}

/**
 * Generates a diff SVG from two pre-computed boolean grids.
 * Grid-agnostic: works with pattern grids, text grids, or any boolean[][] source.
 *
 * Cells shared by both grids are static. Cells unique to From get data-g="a" (visible, animate off).
 * Cells unique to To get data-g="b" (hidden, animate on).
 */
export function generateDiffFromGrids(options: GenerateDiffFromGridsOptions): string {
  const { gridFrom, gridTo, cols, rows, width, height, foregroundColor, backgroundColor } = options;
  const cw = options.cellWidth ?? options.cellSize;
  const ch = options.cellHeight ?? options.cellSize;

  return buildDiffSvg(gridFrom, gridTo, cols, rows, cw, ch, width, height, foregroundColor, backgroundColor);
}

/**
 * Generates a diff SVG from two full configuration objects.
 * Used when the From and To panels have independently configured generator params.
 *
 * The fromConfig provides the base pattern (shown by default).
 * The toConfig provides the target pattern (shown on hover).
 * Colors and canvas settings are taken from fromConfig (these are shared settings).
 *
 * Cells shared by both patterns are static. Cells unique to From get data-g="a" (visible, animate off).
 * Cells unique to To get data-g="b" (hidden, animate on).
 */
export function generateFragmentDiffFromConfigs(options: GenerateFragmentDiffFromConfigsOptions): string {
  const { fromSeed, toSeed } = options;
  const { seedParam: fromSeedParam = 'frequency', ...fromRest } = options.fromConfig;
  const { seedParam: toSeedParam = 'frequency', ...toRest } = options.toConfig;

  const fromConfig = fromSeed ? applySeededParam(fromRest, fromSeed, fromSeedParam) : fromRest;
  const toConfig = toSeed ? applySeededParam(toRest, toSeed, toSeedParam) : toRest;

  // Use fromConfig for canvas/color settings (shared)
  const dims = computeDimensions(fromConfig);
  if (dims.cols <= 0 || dims.rows <= 0) {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><text x="10" y="50" fill="red">Invalid dimensions</text></svg>`;
  }

  const gridFrom = gridFromConfig(fromConfig, dims);
  const gridTo = gridFromConfig(toConfig, dims);

  const { cols, rows, width, height, cellWidth, cellHeight } = dims;
  const { foregroundColor, backgroundColor } = fromConfig;

  return buildDiffSvg(gridFrom, gridTo, cols, rows, cellWidth, cellHeight, width, height, foregroundColor, backgroundColor);
}

// Logo Overlay Helper

/** Inject a logo overlay SVG into a completed SVG string (before closing tag). */
function injectOverlays(
  svg: string,
  width: number,
  height: number,
  logo?: LogoOverlayConfig,
  textOverlay?: TextOverlayConfig,
): string {
  const behindSvg = generateTextOverlaySvg(textOverlay, width, height, 'behind');
  const aboveSvg = generateTextOverlaySvg(textOverlay, width, height, 'above');
  const logoSvg = logo?.enabled ? generateLogoOverlaySvg(logo, width, height) : '';

  if (!behindSvg && !aboveSvg && !logoSvg) return svg;

  let result = svg;

  // "behind" text goes right after the background rect (first <rect.../>)
  if (behindSvg) {
    const bgRectEnd = result.indexOf('/>');
    if (bgRectEnd !== -1) {
      const insertPos = bgRectEnd + 2;
      result = result.slice(0, insertPos) + behindSvg + result.slice(insertPos);
    }
  }

  // "above" text and logo go before closing </svg>
  const suffix = aboveSvg + logoSvg;
  if (suffix) {
    result = result.replace('</svg>', `${suffix}</svg>`);
  }

  return result;
}

// High-Level API (accepts full export JSON)

/**
 * Generates a static SVG from an exported Fragment Maker JSON config.
 * Handles both pattern and text states automatically — the consumer
 * does not need to know which state type the config uses.
 *
 * @param exportData - The full JSON export from Fragment Maker
 * @param options.seed - Optional seed string for per-item variation (pattern states only)
 * @param options.text - Optional text override (text states only). Replaces textConfig.text at render time.
 * @returns SVG string
 *
 * @example
 * ```typescript
 * const exportData = await fetch('/fragment-config.json').then(r => r.json());
 * document.getElementById('hero').innerHTML = generateSvgFromExport(exportData);
 * ```
 */
export function generateSvgFromExport(
  exportData: FragmentExport,
  options?: { seed?: string; text?: string }
): string {
  const { config, fromStateType, fromTextConfig, fonts, logo, textOverlay } = exportData;
  const dims = computeDimensions(config);

  let svg: string;

  if (fromStateType === 'text' && fromTextConfig && fonts) {
    // Text always uses base-cell dimensions (never stretched by elongation)
    const { baseCols, baseRows } = computeBaseDimensions(config);
    const parsedFonts = parseFonts(fonts);
    const effectiveTextConfig = options?.text !== undefined
      ? { ...fromTextConfig, text: options.text }
      : fromTextConfig;
    const { grid } = generateTextGrid(effectiveTextConfig, baseCols, baseRows, parsedFonts);
    svg = gridToSvg(
      grid, baseCols, baseRows,
      config.cellSize, dims.width,
      config.foregroundColor, config.backgroundColor,
      dims.height,
    );
  } else {
    svg = generateFragmentSvg({ config, seed: options?.seed });
  }

  return injectOverlays(svg, dims.width, dims.height, logo, textOverlay);
}

/**
 * Generates an animated diff SVG from an exported Fragment Maker JSON config.
 * Handles all four state type combinations (pattern↔pattern, text↔pattern,
 * pattern↔text, text↔text) automatically.
 *
 * Returns an SVG with `data-g="a"` and `data-g="b"` attributes for animation.
 * Use with `useFragmentReveal` for React, or manipulate the rects directly.
 *
 * @param exportData - The full JSON export from Fragment Maker (must have animation enabled)
 * @param options.fromSeed - Optional seed for the "from" pattern (pattern states only)
 * @param options.toSeed - Optional seed for the "to" pattern (pattern states only)
 * @param options.fromText - Optional text override for the "from" state (text states only)
 * @param options.toText - Optional text override for the "to" state (text states only)
 * @returns SVG string, or empty string if animation is not enabled
 *
 * @example
 * ```typescript
 * const exportData = await fetch('/fragment-config.json').then(r => r.json());
 * const svg = generateDiffSvgFromExport(exportData);
 * container.innerHTML = svg;
 * ```
 */
export function generateDiffSvgFromExport(
  exportData: FragmentExport,
  options?: { fromSeed?: string; toSeed?: string; fromText?: string; toText?: string }
): string {
  const { config, toConfig, fonts, fromStateType, toStateType, fromTextConfig, toTextConfig, logo, textOverlay } = exportData;

  if (!toConfig && !(toStateType === 'text' && toTextConfig)) return '';

  const fromIsText = fromStateType === 'text';
  const toIsText = toStateType === 'text';
  const dims = computeDimensions(config);

  // Both patterns: use the optimized config-based path
  if (!fromIsText && !toIsText && toConfig) {
    const svg = generateFragmentDiffFromConfigs({
      fromConfig: config,
      toConfig,
      fromSeed: options?.fromSeed,
      toSeed: options?.toSeed,
    });
    return injectOverlays(svg, dims.width, dims.height, logo, textOverlay);
  }

  // At least one state is text — use mixed-cell diff with entity grouping.
  const { baseCols, baseRows } = computeBaseDimensions(config);
  if (baseCols <= 0 || baseRows <= 0) return '';

  const elongateAxis = config.elongateAxis ?? 'none';
  const elongateAmount = config.elongateAmount ?? 1;

  const mixedOpts = {
    elongateAxis, elongateAmount, baseCols, baseRows,
    cellSize: config.cellSize, width: dims.width, height: dims.height,
    foregroundColor: config.foregroundColor, backgroundColor: config.backgroundColor,
  };

  let svg: string;

  if (!fromIsText && toIsText && toTextConfig && fonts) {
    // Pattern → Text
    const fromConfig = options?.fromSeed
      ? applySeededParam(config, options.fromSeed, config.seedParam ?? 'frequency')
      : config;
    const parsedFonts = parseFonts(fonts);
    const effectiveToTextConfig = options?.toText !== undefined
      ? { ...toTextConfig, text: options.toText } : toTextConfig;
    svg = buildMixedCellDiffSvg({
      entityGrid: gridFromConfig(fromConfig, dims),
      textGrid: generateTextGrid(effectiveToTextConfig, baseCols, baseRows, parsedFonts).grid,
      ...mixedOpts, patternIsFrom: true,
    });
  } else if (fromIsText && !toIsText && fromTextConfig && fonts && toConfig) {
    // Text → Pattern
    const resolvedToConfig = options?.toSeed
      ? applySeededParam(toConfig, options.toSeed, toConfig.seedParam ?? 'frequency')
      : toConfig;
    const parsedFonts = parseFonts(fonts);
    const effectiveFromTextConfig = options?.fromText !== undefined
      ? { ...fromTextConfig, text: options.fromText } : fromTextConfig;
    svg = buildMixedCellDiffSvg({
      entityGrid: gridFromConfig(resolvedToConfig, computeDimensions(resolvedToConfig)),
      textGrid: generateTextGrid(effectiveFromTextConfig, baseCols, baseRows, parsedFonts).grid,
      ...mixedOpts, patternIsFrom: false,
    });
  } else {
    // Text → Text (or missing data fallback)
    let gridFrom: boolean[][];
    let gridTo: boolean[][];
    if (fromIsText && fromTextConfig && fonts) {
      gridFrom = generateTextGrid(options?.fromText !== undefined
        ? { ...fromTextConfig, text: options.fromText } : fromTextConfig, baseCols, baseRows, parseFonts(fonts)).grid;
    } else {
      const fc = options?.fromSeed ? applySeededParam(config, options.fromSeed, config.seedParam ?? 'frequency') : config;
      gridFrom = gridFromConfig(fc, { cols: baseCols, rows: baseRows, width: dims.width, height: dims.height, cellWidth: config.cellSize, cellHeight: config.cellSize });
    }
    if (toIsText && toTextConfig && fonts) {
      gridTo = generateTextGrid(options?.toText !== undefined
        ? { ...toTextConfig, text: options.toText } : toTextConfig, baseCols, baseRows, parseFonts(fonts)).grid;
    } else if (toConfig) {
      const tc = options?.toSeed ? applySeededParam(toConfig, options.toSeed, toConfig.seedParam ?? 'frequency') : toConfig;
      gridTo = gridFromConfig(tc, { cols: baseCols, rows: baseRows, width: dims.width, height: dims.height, cellWidth: config.cellSize, cellHeight: config.cellSize });
    } else {
      return '';
    }
    svg = generateDiffFromGrids({
      gridFrom, gridTo, cols: baseCols, rows: baseRows,
      cellSize: config.cellSize, width: dims.width, height: dims.height,
      foregroundColor: config.foregroundColor, backgroundColor: config.backgroundColor,
    });
  }

  return injectOverlays(svg, dims.width, dims.height, logo, textOverlay);
}

export interface CellPosition {
  x: number;        // Grid column
  y: number;        // Grid row
  rectElement: SVGRectElement;
}

export interface CellWithDistance extends CellPosition {
  distance: number; // BFS distance from nearest seed
  waveGroup: number; // Animation batch index
}

// Extract grid position from SVG rect
export function extractCellPositions(
  rects: SVGRectElement[],
  cellWidth: number,
  cellHeight?: number
): CellPosition[] {
  const cw = cellWidth;
  const ch = cellHeight ?? cellWidth;
  return rects.map(rect => ({
    x: Math.round(parseInt(rect.getAttribute('x') || '0') / cw),
    y: Math.round(parseInt(rect.getAttribute('y') || '0') / ch),
    rectElement: rect
  }));
}

// BFS distance calculation (4 directions only)
export function calculateDistanceMap(
  gridCols: number,
  gridRows: number,
  seedCells: CellPosition[],
  targetCells: CellPosition[]
): Map<string, number> {
  const distanceMap = new Map<string, number>();
  const queue: Array<{x: number, y: number, dist: number}> = [];

  // Initialize seeds at distance 0
  seedCells.forEach(seed => {
    distanceMap.set(`${seed.x},${seed.y}`, 0);
    queue.push({x: seed.x, y: seed.y, dist: 0});
  });

  // BFS flood fill (4 directions only)
  while (queue.length > 0) {
    const current = queue.shift()!;
    const neighbors = [
      {x: current.x - 1, y: current.y},  // left
      {x: current.x + 1, y: current.y},  // right
      {x: current.x, y: current.y - 1},  // up
      {x: current.x, y: current.y + 1},  // down
    ];

    for (const neighbor of neighbors) {
      if (neighbor.x < 0 || neighbor.x >= gridCols ||
          neighbor.y < 0 || neighbor.y >= gridRows) continue;

      const key = `${neighbor.x},${neighbor.y}`;
      const isTargetCell = targetCells.some(c => c.x === neighbor.x && c.y === neighbor.y);

      if (isTargetCell && !distanceMap.has(key)) {
        const newDist = current.dist + 1;
        distanceMap.set(key, newDist);
        queue.push({...neighbor, dist: newDist});
      }
    }
  }

  return distanceMap;
}

/**
 * Group cells by their entity ID (data-eid attribute) so all cells in the
 * same elongated entity get the same BFS distance → animate as one unit.
 */
export function applyEntityGrouping(cells: CellWithDistance[]): void {
  const entityGroups = new Map<string, CellWithDistance[]>();

  for (const cell of cells) {
    const eid = cell.rectElement.getAttribute('data-eid');
    if (eid) {
      let group = entityGroups.get(eid);
      if (!group) {
        group = [];
        entityGroups.set(eid, group);
      }
      group.push(cell);
    }
  }

  // All cells in an entity get the minimum distance of the group
  for (const group of entityGroups.values()) {
    const minDist = Math.min(...group.map(c => c.distance));
    for (const cell of group) {
      cell.distance = minDist;
    }
  }
}

// Group cells into animation waves with randomization for organic feel
export function groupIntoWaves(
  cellsWithDistance: CellWithDistance[],
  targetFrames: number
): CellWithDistance[] {
  if (cellsWithDistance.length === 0) return [];

  // Add random tie-breaker to each cell for stable randomization
  const cellsWithTieBreaker = cellsWithDistance.map(cell => ({
    ...cell,
    tieBreaker: Math.random()
  }));

  // Sort by distance first, then by random tie-breaker for same distance
  const sorted = cellsWithTieBreaker.sort((a, b) => {
    const distDiff = a.distance - b.distance;
    if (Math.abs(distDiff) < 0.1) {
      // Same distance level - use stable tie-breaker
      return a.tieBreaker - b.tieBreaker;
    }
    return distDiff;
  });

  // Assign continuous wave values for smoother animation
  // Start from 1 instead of 0 to avoid immediate visibility at progress=0
  return sorted.map((cell, index) => ({
    ...cell,
    waveGroup: ((index + 1) / sorted.length) * targetFrames
  }));
}

export function useReducedMotion(): boolean {
  const [reducedMotion, setReducedMotion] = useState(() => {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  });

  useEffect(() => {
    const mql = window.matchMedia('(prefers-reduced-motion: reduce)');
    const onChange = (e: MediaQueryListEvent) => setReducedMotion(e.matches);
    mql.addEventListener('change', onChange);
    return () => mql.removeEventListener('change', onChange);
  }, []);

  return reducedMotion;
}

interface AnimState {
  aCellsOrdered: CellWithDistance[];  // "From" cells sorted by distance
  bCellsOrdered: CellWithDistance[];  // "To" cells sorted by distance
  sharedCells: CellPosition[];        // Seed points for growth
  connectionPath: CellPosition[];     // Temporary rects for snake animation

  aMaxWave: number;                   // Cache max wave for performance
  bMaxWave: number;                   // Cache max wave for performance

  startTime: number;
  currentProgress: number;            // Track current progress (0-1) for smooth reversal
  initialProgress: number;            // Progress when current animation phase started
  currentPhase: 'connection' | 'transition' | 'complete';
  direction: 'forward' | 'backward' | 'idle';
  animFrameId: number | null;
}

// Create snake connection path (Bresenham's line)
function createConnectionPath(
  fromCell: CellPosition,
  toCell: CellPosition,
  cellWidth: number,
  cellHeight: number,
  svg: SVGSVGElement
): CellPosition[] {
  const path: CellPosition[] = [];

  // Bresenham's line algorithm
  let x0 = fromCell.x, y0 = fromCell.y;
  const x1 = toCell.x, y1 = toCell.y;
  const dx = Math.abs(x1 - x0);
  const dy = Math.abs(y1 - y0);
  const sx = x0 < x1 ? 1 : -1;
  const sy = y0 < y1 ? 1 : -1;
  let err = dx - dy;

  while (x0 !== x1 || y0 !== y1) {
    const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    rect.setAttribute('x', String(x0 * cellWidth));
    rect.setAttribute('y', String(y0 * cellHeight));
    rect.setAttribute('width', String(cellWidth));
    rect.setAttribute('height', String(cellHeight));
    rect.setAttribute('fill', 'currentColor');
    rect.setAttribute('opacity', '0');
    rect.setAttribute('data-connection', 'true');

    svg.appendChild(rect);
    path.push({x: x0, y: y0, rectElement: rect as SVGRectElement});

    const e2 = 2 * err;
    if (e2 > -dy) { err -= dy; x0 += sx; }
    if (e2 < dx) { err += dx; y0 += sy; }
  }

  return path;
}

export function useFragmentReveal(
  containerRef: React.RefObject<HTMLDivElement | null>,
  durationMs: number = 600,
  enabled: boolean = true
) {
  const stateRef = useRef<AnimState>({
    aCellsOrdered: [],
    bCellsOrdered: [],
    sharedCells: [],
    connectionPath: [],
    aMaxWave: 0,
    bMaxWave: 0,
    startTime: 0,
    currentProgress: 0,
    initialProgress: 0,
    currentPhase: 'complete',
    direction: 'idle',
    animFrameId: null,
  });
  const reducedMotion = useReducedMotion();

  useEffect(() => {
    return () => {
      if (stateRef.current.animFrameId !== null) {
        cancelAnimationFrame(stateRef.current.animFrameId);
        stateRef.current.animFrameId = null;
      }
    };
  }, []);

  const tick = useCallback((timestamp: number) => {
    const s = stateRef.current;

    if (!s.startTime) {
      s.startTime = timestamp;
    }

    const elapsed = timestamp - s.startTime;
    let progress = Math.min(elapsed / durationMs, 1);

    // Calculate effective progress based on direction
    // Use initialProgress (set once at animation start) to avoid exponential compounding
    let effectiveProgress: number;
    if (s.direction === 'forward') {
      // Linearly interpolate from initialProgress to 1.0
      effectiveProgress = s.initialProgress + (progress * (1.0 - s.initialProgress));
      effectiveProgress = Math.min(effectiveProgress, 1.0);
    } else if (s.direction === 'backward') {
      // Linearly interpolate from initialProgress to 0.0
      effectiveProgress = s.initialProgress * (1.0 - progress);
      effectiveProgress = Math.max(effectiveProgress, 0);
    } else {
      return;
    }

    if (s.direction === 'forward') {
      // Trigger final frame slightly early (at 98% progress) to ensure smooth completion
      if (progress >= 0.98) {
        // Final frame - directly set all cells to final state, no wave calculations
        s.aCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '0');
        s.bCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '1');
        s.connectionPath.forEach(cell => cell.rectElement.remove());
        s.connectionPath = [];
        s.currentProgress = 1.0;
        s.currentPhase = 'complete';
        s.direction = 'idle';
        s.animFrameId = null;

      } else {
        // Normal frames - wave-based animation
        s.currentProgress = effectiveProgress;

        const aCurrentWave = effectiveProgress * s.aMaxWave;
        const bCurrentWave = effectiveProgress * s.bMaxWave;

        s.aCellsOrdered.forEach(cell => {
          if (cell.waveGroup <= aCurrentWave) {
            cell.rectElement.style.opacity = '0';
          } else {
            cell.rectElement.style.opacity = '';
          }
        });

        s.bCellsOrdered.forEach(cell => {
          if (cell.waveGroup <= bCurrentWave) {
            cell.rectElement.style.opacity = '1';
          } else {
            cell.rectElement.style.opacity = '0';
          }
        });

        s.animFrameId = requestAnimationFrame(tick);
      }
    } else if (s.direction === 'backward') {
      // Cleanup connection paths
      if (s.connectionPath.length > 0) {
        s.connectionPath.forEach(cell => cell.rectElement.remove());
        s.connectionPath = [];
      }

      // Trigger final frame slightly early (at 98% progress) to ensure smooth completion
      if (progress >= 0.98) {
        // Final frame - directly set all cells to initial state
        s.aCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '');
        s.bCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '0');
        s.currentProgress = 0;
        s.direction = 'idle';
        s.animFrameId = null;

      } else {
        // Normal frames - use same wave logic as forward; decreasing effectiveProgress
        // naturally reverses the animation without any visual discontinuity
        s.currentProgress = effectiveProgress;

        const aCurrentWave = effectiveProgress * s.aMaxWave;
        const bCurrentWave = effectiveProgress * s.bMaxWave;

        s.aCellsOrdered.forEach(cell => {
          if (cell.waveGroup <= aCurrentWave) {
            cell.rectElement.style.opacity = '0';
          } else {
            cell.rectElement.style.opacity = '';
          }
        });

        s.bCellsOrdered.forEach(cell => {
          if (cell.waveGroup <= bCurrentWave) {
            cell.rectElement.style.opacity = '1';
          } else {
            cell.rectElement.style.opacity = '0';
          }
        });

        s.animFrameId = requestAnimationFrame(tick);
      }
    }
  }, [durationMs]);

  const ensureRects = useCallback((): boolean => {
    const s = stateRef.current;

    // Check if rects are already initialized and connected
    if (
      (s.aCellsOrdered.length > 0 && s.aCellsOrdered[0].rectElement.isConnected) ||
      (s.bCellsOrdered.length > 0 && s.bCellsOrdered[0].rectElement.isConnected)
    ) return true;

    const container = containerRef.current;
    if (!container) return false;

    const svg = container.querySelector('svg');
    if (!svg) return false;

    // 1. Query all rect elements
    const aRects = Array.from(svg.querySelectorAll('rect[data-g="a"]')) as SVGRectElement[];
    const bRects = Array.from(svg.querySelectorAll('rect[data-g="b"]')) as SVGRectElement[];
    const sharedRects = Array.from(svg.querySelectorAll('rect:not([data-g])')) as SVGRectElement[];

    if (aRects.length === 0 && bRects.length === 0) return false;

    // 2. Extract positions
    // Use minimum rect size as base cell size (handles mixed-size rects from elongated diffs)
    const allRects = [...aRects, ...bRects, ...sharedRects];
    if (allRects.length === 0) return false;

    let minW = Infinity, minH = Infinity;
    for (const r of allRects) {
      const w = parseInt(r.getAttribute('width') || '1');
      const h = parseInt(r.getAttribute('height') || '1');
      if (w < minW) minW = w;
      if (h < minH) minH = h;
    }
    const cellWidth = minW;
    const cellHeight = minH;

    const viewBox = svg.getAttribute('viewBox')?.split(' ') || [];
    const gridCols = Math.round(parseInt(viewBox[2] || '1056') / cellWidth);
    const gridRows = Math.round(parseInt(viewBox[3] || '1056') / cellHeight);

    // Always extract positions using base cell size so all rects map to the same grid
    const aCells = extractCellPositions(aRects, cellWidth, cellHeight);
    const bCells = extractCellPositions(bRects, cellWidth, cellHeight);
    const sharedCells = extractCellPositions(sharedRects, cellWidth, cellHeight);

    // 3. Determine seed points
    let seedCells = sharedCells;
    if (seedCells.length === 0 && aCells.length > 0 && bCells.length > 0) {
      // Find nearest pair for connection path
      let minDist = Infinity;
      let nearestA: CellPosition | null = null;
      let nearestB: CellPosition | null = null;

      aCells.forEach(a => {
        bCells.forEach(b => {
          const dist = Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
          if (dist < minDist) {
            minDist = dist;
            nearestA = a;
            nearestB = b;
          }
        });
      });

      if (nearestA && nearestB) {
        s.connectionPath = createConnectionPath(nearestA, nearestB, cellWidth, cellHeight, svg);
        seedCells = [nearestA, nearestB]; // Use both endpoints as seeds
      }
    }

    // 4. Calculate distances
    const aDistances = calculateDistanceMap(gridCols, gridRows, seedCells, aCells);
    const bDistances = calculateDistanceMap(gridCols, gridRows, seedCells, bCells);

    // Handle orphaned cells (unreachable by BFS)
    const maxADistance = aDistances.size > 0 ? Math.max(...Array.from(aDistances.values())) : 0;
    const maxBDistance = bDistances.size > 0 ? Math.max(...Array.from(bDistances.values())) : 0;

    // 5. Attach distances to cells
    const aCellsWithDist = aCells.map(cell => ({
      ...cell,
      distance: aDistances.get(`${cell.x},${cell.y}`) ?? (maxADistance + 1),
      waveGroup: 0
    }));

    const bCellsWithDist = bCells.map(cell => ({
      ...cell,
      distance: bDistances.get(`${cell.x},${cell.y}`) ?? (maxBDistance + 1),
      waveGroup: 0
    }));

    // 5b. Group entity cells so elongated bars animate as units
    applyEntityGrouping(aCellsWithDist);
    applyEntityGrouping(bCellsWithDist);

    // 6. Group into waves
    const targetFrames = Math.max(1, Math.ceil(durationMs / 16.67));
    s.aCellsOrdered = groupIntoWaves(aCellsWithDist, targetFrames);
    s.bCellsOrdered = groupIntoWaves(bCellsWithDist, targetFrames);
    s.sharedCells = sharedCells;

    // Cache max wave values for performance
    // Multiply by 1.05 so all cells animate before effectiveProgress reaches 0.95
    s.aMaxWave = s.aCellsOrdered.length > 0
      ? Math.max(...s.aCellsOrdered.map(c => c.waveGroup)) * 1.05
      : 0;
    s.bMaxWave = s.bCellsOrdered.length > 0
      ? Math.max(...s.bCellsOrdered.map(c => c.waveGroup)) * 1.05
      : 0;

    return true;
  }, [containerRef, durationMs]);

  const onMouseEnter = useCallback(() => {
    if (!enabled) return;
    if (!ensureRects()) return;
    const s = stateRef.current;

    if (reducedMotion) {
      // Instant transition for reduced motion
      s.aCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '0');
      s.bCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '1');
      s.connectionPath.forEach(cell => cell.rectElement.remove());
      s.connectionPath = [];
      s.currentProgress = 1;
      return;
    }

    // Cancel existing animation if running
    if (s.animFrameId !== null) {
      cancelAnimationFrame(s.animFrameId);
    }

    s.initialProgress = s.currentProgress;
    s.direction = 'forward';
    s.startTime = 0;
    s.animFrameId = requestAnimationFrame(tick);
  }, [tick, reducedMotion, enabled, ensureRects]);

  const onMouseLeave = useCallback(() => {
    if (!enabled) return;
    const s = stateRef.current;
    if (s.aCellsOrdered.length === 0 && s.bCellsOrdered.length === 0) return;

    if (reducedMotion) {
      // Instant reverse for reduced motion
      s.aCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '');
      s.bCellsOrdered.forEach(cell => cell.rectElement.style.opacity = '0');
      s.connectionPath.forEach(cell => cell.rectElement.remove());
      s.connectionPath = [];
      s.currentProgress = 0;
      return;
    }

    // Cancel existing animation if running
    if (s.animFrameId !== null) {
      cancelAnimationFrame(s.animFrameId);
    }

    s.initialProgress = s.currentProgress;
    s.direction = 'backward';
    s.startTime = 0;
    s.animFrameId = requestAnimationFrame(tick);
  }, [tick, reducedMotion, enabled]);

  return { onMouseEnter, onMouseLeave };
}

/**
 * Observes a container element and returns its size snapped to the nearest
 * cell boundary. This ensures the SVG grid aligns cleanly with the container
 * without partial cells or wasted space.
 *
 * Only triggers a re-render when the size changes by at least one full cell,
 * avoiding unnecessary SVG regeneration on sub-pixel resize events.
 *
 * @param containerRef - Ref to the container element to observe
 * @param cellSize - The cell size from your FragmentConfig (e.g. `config.cellSize`)
 * @returns `{ width, height }` snapped to cell boundaries, or `null` before first measurement or if cellSize is undefined
 */
export function useFragmentSize(
  containerRef: React.RefObject<HTMLElement | null>,
  cellSize: number | undefined
): { width: number; height: number } | null {
  const [size, setSize] = useState<{ width: number; height: number } | null>(
    null
  );
  const lastSize = useRef<{ width: number; height: number } | null>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el || cellSize === undefined) return;

    const observer = new ResizeObserver(entries => {
      const { width, height } = entries[0].contentRect;
      if (width <= 0 || height <= 0) return;

      const w = Math.ceil(width);
      const h = Math.ceil(height);
      const prev = lastSize.current;

      if (
        !prev ||
        Math.abs(w - prev.width) >= cellSize ||
        Math.abs(h - prev.height) >= cellSize
      ) {
        const snapped = { width: w, height: h };
        lastSize.current = snapped;
        setSize(snapped);
      }
    });

    observer.observe(el);
    return () => observer.disconnect();
  }, [containerRef, cellSize]);

  return size;
}
